/* 1 when the byte sum of the save block DS:0042..27be equals the slot's checksum. */
uint16_t opeu_saved_game_valid(uint8_t ds[65536], uint8_t slot) {
  BYTE_POINTER a;
  uint16_t     b;
  b = 0;
  for (a = FIRST_BYTE; a <= LAST_BYTE; a++)
    b += BYTE_AT(a);
  if (CHECKSUM(slot) == b)
    return 1;
  return 0;
}

/* Bytes of one saved game record: DS:0042..27be. */
uint16_t opeu_save_record_size(void) {
  return RECORD_SIZE();
}

/* Load menu: reads the 20 slot headers from SAVEDATA, lets the player choose
 * a slot, loads and rebases that record and reports whether it is valid.
 * Returns the menu choice, or 0 when nothing valid was loaded. */
uint16_t opeu_load_saved_game(uint8_t ds[65536], HostEvent event) {
  int          a;
  SLOT_POINTER b;
  uint8_t      c;
  int          d;
  ATTRIBUTE(4);
  if (!EXISTS(TEXT(opeu_savedata_name, 0x4560))) {
    PRINT(TEXT(opeu_load_print_format, 0x4583),
          FRAMED(32, 188, TEXT(opeu_no_saved_games_text, 0x4569)));
    a = 0;
    UI_WAIT(23);
    ATTRIBUTE(0);
  } else {
    ATTRIBUTE(0);
    d = OPEN(TEXT(opeu_load_savedata_name, 0x4586));
    for (c = 0; c < 20; c++)
      READ(d, SLOT_AT(c), 12);
    ATTRIBUTE(4);
    UI_TEXT(FRAMED(33, 336, TEXT(opeu_load_which_text, 0x458f)));
    ATTRIBUTE(0);
    if ((a = MENU_CHOOSE(SAVE_MENU, 1, 3)) != 0) {
      ATTRIBUTE(4);
      UI_TEXT(FRAMED(32, 188, TEXT(opeu_loading_text, 0x45a0)));
      SEEK(d, (long)SIZE() * SAVE_SLOT + 240, 0);
      READ(d, 0x42u, SIZE());
      REBASE();
      b = SLOT_AT(SAVE_SLOT);
      if (VALID(SAVE_SLOT) && SLOT_SCENARIO(b) != 6)
        UI_TEXT(FRAMED(29, 188, TEXT(opeu_loaded_text, 0x45b6)));
      else {
        UI_TEXT(FRAMED(29, 188, TEXT(opeu_load_failed_text, 0x45d2)));
        a = 0;
      }
      UI_WAIT(15);
      ATTRIBUTE(0);
    }
    CLOSE(d);
  }
  BACKDROP(1);
  return a;
}

